// Parse hybrid search parameters
const query = $json.query || $json.body?.query || '';
const limit = $json.limit || $json.body?.limit || 10;
const vectorWeight = $json.vector_weight || $json.body?.vector_weight || 0.7;
const keywordWeight = $json.keyword_weight || $json.body?.keyword_weight || 0.3;
const candidateMultiplier = $json.candidate_multiplier || $json.body?.candidate_multiplier || 3;
const filters = $json.filters || $json.body?.filters || {};

return {
  json: {
    query,
    limit,
    vector_weight: vectorWeight,
    keyword_weight: keywordWeight,
    candidate_multiplier: candidateMultiplier,
    filters
  }
};

// Format hybrid search results
const response = $json;

if (response.status === 'error') {
  return {
    json: {
      success: false,
      error: response.message,
      results: []
    }
  };
}

const results = (response.results || []).map(result => ({
  document_id: result.document_id,
  document_name: result.metadata?.document_name || result.document_name,
  content_preview: (result.text || '').substring(0, 250),
  relevance_score: result.score || 0,
  vector_score: result.vector_score || 0,
  keyword_score: result.keyword_score || 0,
  department: result.metadata?.department,
  document_type: result.metadata?.document_type,
  document_url: result.metadata?.document_url,
  chunk_type: result.metadata?.chunk_type,
  keywords: result.metadata?.keywords ? JSON.parse(result.metadata.keywords) : []
}));

return {
  json: {
    success: true,
    results,
    metadata: {
      query: response.query,
      search_type: 'hybrid',
      vector_weight: response.vector_weight,
      keyword_weight: response.keyword_weight,
      total_results: results.length
    }
  }
};
